    "id": "mi5",
    "title": "Test 5",
    "passage": "Strictly speaking, cartography is the drawing or compiling of maps. The explorers and surveyors go out and make the measurements and gather the information from which the cartographers draw their maps. Sometimes the fieldwork and the creation of the map are done by the same person. But when the scope is broad and the sources of information many, maps are more often a compilation of that information. They represent the accumulated work of many people, brought together under the supervision of one person, the compiler. The value of the map depends, of course, on the expertise of the compiler, who must sift through available information, select the most accurate data, and come up with a thoughtful and accurate synthesis of the geographic knowledge of the region.",
