    "id": "mi6",
    "title": "Test 6",
    "passage": "Hawaii was originally settled by the natives of the South Pacific, who arrived in the islands in canoes laden with breadfruit, yams, taro, coconut, bananas, pigs, and chickens. Supplementing these foods were over a hundred different edible fishes and 40 kinds of seaweed from the surrounding waters. Hawaiian food was eaten raw or wrapped in taro leaves, seasoned with coconut, and cooked. In the early 1800s, the whalers and missionaries introduced stews, chowders, curries, corned beef, dried beef, salt salmon, and Indian and cornstarch puddings. Most likely, pipkaula (jerked beef), lomi lomi salmon, and haupia (coconut pudding) evolved during this period. In the late nineteenth century immigrants from China, Japan, and Korea were brought to Hawaii to work the sugar plantations. The Chinese brought rice, soybeans, and vegetables and their ways of cooking them. The Japanese brought sukiyaki and teriyaki, among many other foods. Settlers from the Continental United States also brought their favorite recipes and in the spirit of aloha, the Hawaiians have accepted each group's offerings and drawn the best from them. Thus a Hawaiian feast is a gastronomic experience, the essence of Hawaii and its many cultures.",
