    "id": "v10",
    "title": "Test 10",
    "passage": "There are three main types of sedimentary rocks, which are classified according to the origin and size of their particles. One type, called evaporites, is formed from chemically derived sediments. For example, an inland sea might evaporate and leave a deposit of rock salt. The second type is derived entirely from organic material. Since it is a fossil in its own right, it is called fossiliferous rock. Fossiliferous rocks, such as limestones and chalks, are formed from calcium-based skeletons of tiny organisms deposited on the seabed. Some limestones are fossilized corals; others, known as tufa, are derived from mosses and other plants that grow beside hot springs. Carbon-based rocks, such as coal and jet, are the remains of plant material laid down in huge quantities. The remains of sponges and microscopic diatoms constitute rocks such as chert and flint. The third type of sedimentary rock is clastic. It is formed from eroded particles of other rocks and is graded according to the size of these particles. Fine shales are perhaps the most significant sedimentary rocks covering the earth. The sedimentary rocks most likely to contain fossils are those that were laid down in places where there was abundant life and where deposition was rapid enough to bury the organisms before their bodies were broken up and decomposed. The sandy bottoms of shallow, calm seas, river deltas, lagoons, and deserts are the most likely places to give rise to fossils. The finer the sediment, the finer the detail recorded in them. Details such as the fur of those reptilian flyers, the pterosaurs, are only visible because they were fossilized in exceptionally fine limestone.",
