    "id": "v11",
    "title": "Test 11",
    "passage": "On a drop shot, a tennis player “drops” the ball just over the net, hoping that his or her opponent won’t get to it at all or will just barely reach it, thus making a weak return. The drop shot works well in a number of situations. It can be used to tire an opponent, to bring a baseline player to the net, to win points outright when an opponent is slow in moving forward or is out of position, or to substitute for the approach shot. A perfect situation for a drop shot occurs when a player’s opponent is far out of court and hits well to the inside of the service line. A good drop shot is a sure winner, but a bad one is equally certain disaster. The opponent who gets to the ball early has been handed the net position, which is a distinct advantage for the net rusher who will usually win the point in short order. There are two types of drop shots, each requiring a distinct stroke. The first is used to drop slow balls descending from the peak of the bounce. The second is used on rising balls. These shots require excellent timing and a simple stroke, such as the swing on waist-high volleys.",
