    "id": "v14",
    "title": "Test 14",
    "passage": "Planes are subjected to drag forces because an object moving forward through the air is hampered by it to a greater or lesser extent, since the air or any gas has friction. A plane in subsonic flight is preceded by the pressure waves it creates as it makes its way through the air. These pressure waves push away the air in front of the plane so there is less drag than would otherwise be the case. But when a plane reaches sonic speed, or the speed of sound, the pressure waves no longer precede the plane. They no longer push away any of the air in front of the craft, so the drag forces become much greater. The large rise in drag as the plane approaches Mach 1, or the speed of sound, is referred to as the sonic barrier. Even a conventional subsonic plane traveling at a speed below Mach 1 can encounter an extreme rise in drag. This is because the pressure over the wing is decreased as the wing moves through the air. This results from the increase in the speed of the air stream over the wing in accordance with the law of physics called Bernoulli’s principle.",
