    "id": "d13",
    "title": "Test 13",
    "passage": "The study of control processes in electronic, mechanical, and biological systems is known as cybernetics. The word was coined in 1948 by the American mathematician Norbert Wiener from the Greek word meaning pilot or steersman. Cybernetics is concerned with the analysis of the flow of information in both living organisms and machines, but it is particularly concerned with systems that are capable of regulating their own operations without human control. Automatic regulation is accomplished by using information about the state of the end product that is fed back to the regulating device, causing it to modify or correct production procedures if necessary. The concept of feedback is at the very heart of cybernetics and is what makes a system automatic and self-regulating. A simple example of a self-regulating machine is a thermostat, which reacts to continual feedback about the outside temperature and responds accordingly to achieve the temperature that has been programmed into it. The applications of cybernetics are wide reaching, appearing in science, engineering, technology, sociology, economics, education, and medicine. Computers can keep a patient alive during a surgical operation, making instantaneous modifications based on a constant flow of information. In education, teaching machines use cybernetic principles to instruct students on an individual basis. In the home, automation is present in such everyday products as refrigerators, coffee makers, and dishwashers. In industry, automation is increasing its applications, although it is currently applied primarily to the large-scale production of single units. In industries in which a break in the flow of production can ruin the product, automatic controls are invaluable. Chemical and petroleum plants are now almost completely automatic, as are industries involved in the production of chemicals and atomic energy. Automation has become the answer when human safety is the number one priority.",
