        "correct": 0,
        "explanation": "Câu hỏi yêu cầu tìm thông tin tại sao loài bướm đêm này được đặt tên là “bướm đêm hổ”. Xem xét 4 đáp án được đưa ra, các từ khóa cần lưu tâm ở từng đáp án đó là “coloration” (Đáp án A), “predator” (đáp án B), “habitat” (đáp án C) và “scientific classification” (đáp án D). Đọc lướt cả bài, ta thấy rằng không có câu nào đề cập đến “habitat” (môi trường sống) (hoặc từ đồng nghĩa với nó như “home); tương tự, không có thông tin liên quan đến “science” hay “scientific classification” (sự phân loại có tính khoa học). →Do đó, C và D không phù hợp. →Đáp án A. Màu sắc của loài bướm này giống với màu sắc của hổ. Theo như đã đọc và hiểu ở câu (3) Loài bướm này dễ dàng được nhận biết với những đốm và đường kẻ sọc màu cam và đen hoặc vàng và đen trên đôi cánh, trên thực tế, ta thấy da hổ cũng có những đốm và kẻ sọc màu cam và đen/ hoặc vàng đen →Có sự tương đồng về màu sắc giữa cánh của loài bướm này và da hổ. →A đúng. Đáp án B. Nó là một loài động vật ăn thịt hung ác giống như hổ. Đọc thông tin ở các câu có chứa từ “predator”. (4) Kiểu kết hợp màu sắc theo hình thức nổi bật như vậy là điều thông thường trong thế giới động vật, có vai trò cảnh báo những loài động vật ăn thịt rằng chúng có vị và mùi khó chịu. (5) Đây là chức năng hiển nhiên được mang lại bởi màu sắc nổi bật của loài bướm đêm hổ trong vườn, loài vật nhìn thì khá bắt mắt nhưng lại có độc cho kẻ săn mồi. (7) Bướm đêm hổ quả thực là một ví dụ rõ ràng nhất cho quan điểm rằng nhiều động vật ăn thịt hiểu là những sinh vật có màu sắc tươi sáng nhất thường là những loài không phù hợp nhất để ăn. Các thông tin này chỉ đề cập đến những loài động vật có ý định ăn thịt bướm đêm hổ mà không nhắc đến bướm đêm hổ với vai trò làm kẻ săn mồi hay động vật ăn thịt. →B loại. →A là đáp án đúng"
