    "id": "c1",
    "title": "Test 1",
    "passage": "Somewhere on every good map there is a legend. A legend is a small drawing. It tell us how to read the map. It shows how the cartographer made the map. No single map can show everything. It would be too crowded. The legend tells us which things the cartographer chose to show. It shows which areas the map covers. [A] The map is only a flat piece of paper. The legend tells us how it shows the earth’s curve. There is one very important thing on a legend. This is the map’s scale. The scale has two parts. One part is called a verbal scale. It uses words. Here is an example: 1 millimeter equals 100 kilometers. [B] The other part of the scale is a line or a bar. This is called a graphic scale. On it, one small mark, usually a millimeter, stands for a real distance. In the previous example, the distance of a millimeter is 100 kilometers. Most of the scales on road maps are graphic scales. With the scale, you can tell the distance from place to place. The legend also tells what the symbols on the map mean. For example, the cartographer might use a star to show a big city. A red star inside a dot might show a country’s capital city. A small, black dot might show a small town. Colors and lines are very important symbols. A river may be colored blue. A very busy highway might be a thick, red line. A small road might be a thin, black line. A footpath might be a thin, broken line on the map. [C]\nSome maps show places that don’t have roads or cities. [D] These maps can show how high or steep mountains are. They can also show where the land is flat. The map will show these things with many different colors. This kind of map is called a topographical map. Its legend will tell how to read these things.",
