    "id": "c4",
    "title": "Test 4",
    "passage": "Comets, asteroids, and meteors are part of a similar group of space objects. All pass through space, but are small and not part of a planet. These space objects, though, differ in what they are made of. Comets are made mostly of ice and a little dust. When a comet travels near the sun, the sun melts some of its ice. The melted ice becomes a cloud of steam and dust. The comet could even blow up! The sun’s wind blows the steam and dust. This gives the comet a tail. The tail can be 1.6 million kilometers long or even longer. Sometimes, we can see these near Earth. Each time a comet goes near the sun, its tail gets smaller. Finally, its tail vanishes. [A] Asteroids, on the other hand, contain little ice but are mainly made of rock or dust. Asteroids are small, rocky pieces that travel in space. Many of the biggest asteroids orbit between Mars and Jupiter. The largest asteroid there is 933 kilometers across. Another group of asteroids travels the same path as Jupiter. Some asteroids are even near Earth. These sometimes hit the Earth. [B] The smallest asteroids are only ten or twenty meters across. There may be many others so small that we can’t find them. All of the asteroids together are about the size of Earth’s moon. Every asteroid is different! Some are very light. They may be made of many small pieces. Others are made of metal or hard rock. Sometimes, asteroids have small moons. Sometimes, they move together in pairs. [C] Most asteroids have unusual shapes because they crash into other things. We can’t see asteroids with our naked eyes. We can only see them through telescopes. Meteors are similar to asteroids in composition. They are small pieces of dust and rock that fall to Earth. They fall very, very quickly into Earth’s airspace. This makes them burn. Meteors make bright trails of light across the sky, which we call shooting stars. Most meteors are very small. Sometimes, many meteors fall together. [D] These are called meteor showers. At other times, a bigger rock piece falls. It makes an even brighter trail. This is called a fireball. Sometimes, it doesn’t finish burning before it hits the ground. This kind of rock is called a meteorite.",
