    "passage": "Look at the stars in the night sky. Do some of them seem to form patterns or designs? Can you see animals, people, or objects? These patterns are called constellations. [A] Constellations are not real animals, people, or objects. We imagine them to help us make a map of the sky. On a dark night, you can see almost 1,500 stars. Trying to distinguish which is which can be difficult. Constellations make it easier for us to identify stars. People began seeing patterns in the stars about 6,000 years ago. [B] Three of the first constellations they imagined were a lion, a bull, and a scorpion. In ancient times, farmers used constellations to know which month it was. We can see some constellations only one season each year. Farmers knew it was time to plant when they saw a certain constellation. They knew it was time to harvest when they saw a different one. [C] People in different countries can look at the same constellation and imagine different things. Someone in China might think a constellation looks like a dragon. Someone in Australia might think the same pattern is a horse. Each country has its own ideas. Many constellations get their names from the myths of ancient Greece and Rome. A constellation called Aquarius is named after a Greek boy who carried water. A constellation called Taurus is named after a god who came to earth as a bull. Constellations are not stationary. The stars in them are gradually moving. It is difficult to know the boundaries of many constellations. In 1929, international astronomers, scientists who study stars, agreed on official boundaries for the 88 constellations that exist today. [D] However, by the time your children grow up, these boundaries could change. We might also find new constellations. We will always use our imaginations to help understand the world around us.",
